/* Editable second step. Local examples simulate the future Agent response. */
(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x));
const limits={genre:3,core:3,style:5};
const labels={title:'Project title',audience:'Audience',genre:'Genre',core:'Premise',style:'Style',world:'Worldbuilding',highlights:'Story hook',synopsis:'Story synopsis'};
const split=(text,max)=>String(text||'').split(/[、,，;；\n]+/).map(x=>x.trim()).filter(Boolean).slice(0,max);
function sync(p){const d=p.agent.planning;p.title=d.title||'未命名故事';p.story=d.synopsis;p.facts=d.world;Object.assign(p.settings,{audience:d.audience,genre:d.genre.join('、'),core:d.core.join('、'),style:d.style.join('、')});}
function enter(p,text,manual,example){const settings=clone(p.settings),prior=p.agent.planning;let d=prior?clone(prior):{title:'',audience:settings.audience||'',genre:split(settings.genre,3),core:split(settings.core,3),style:split(settings.style,5),world:'',highlights:'',synopsis:manual?text:''};
 if(!manual){const romance=text===example.seed||/前女友|前男友|离城/.test(text)&&/重逢|三年|爱情/.test(text);const clock=/钟表|旧表|修表/.test(text)&&/未来|留言/.test(text);const fantasy=/魔法|奇幻|精灵|穿越|龙族/.test(text),suspense=/悬疑|失踪|谜|侦探|未来|留言/.test(text);const generated=romance?{title:'离城之前',audience:'大众向',genre:['都市','爱情'],core:['破镜重圆','离城倒计时','双向成长'],style:['克制细腻','生活感','开放式结局'],world:'当代普通城市。陆川即将离开海汀，前往南州工作。故事从周四夜延续到周日离城，人物在日常生活中面对关系与未来的选择。',highlights:'用离城倒计时推动旧情重逢；复合不以放弃个人生活为代价，悬念落在下一次共同选择。',synopsis:example.synopsis}:clock?{title:'来自明天的旧表',audience:'大众向',genre:['悬疑','奇幻'],core:['未来留言','时间代价','小人物抉择'],style:['悬念递进','细节伏笔','温暖底色'],world:'当代城市的一间旧钟表铺。被修复的钟表会短暂传来未来的留言；信息并不完整，每次干预都会改变留言所指向的结果。',highlights:'每一只旧表带出一位委托人的秘密。修复器物与修复人生相互照应，主角越想挽回遗憾，越需要面对改变未来的代价。',synopsis:text+'\n\n钟表匠起初利用留言帮助委托人避开意外，却发现被改变的未来会以另一种方式重现。当一只与自己过去有关的旧表被送到店里，他必须在提前知道答案与尊重他人选择之间作出决定。最终，他尝试不再替所有人安排结局，而是把选择的机会交还给他们。'}:{title:text.match(/《([^》]+)》/)?.[1]||text.replace(/[\s，。！？：:]/g,'').slice(0,10)+' · 故事草案',audience:'大众向',genre:[fantasy?'奇幻':suspense?'悬疑':'剧情'],core:[settings.core||text.split(/[。！？\n]/)[0].slice(0,36),'人物选择'],style:[fantasy?'想象力':suspense?'悬念递进':'人物驱动','情感真实'],world:'以你的原始设定为基础：'+text+'\n\n补全建议：将主要行动集中在同一段连续时间内，世界规则保持一致。时代、地点与特殊规则可以在这里进一步明确。',highlights:'围绕原始想法中的核心变化，突出人物选择与行动后果，让开场悬念在结局得到回应。',synopsis:text+'\n\n建议发展：主角因这一事件被迫采取行动，在解决问题的过程中发现更深的阻碍。一次关键选择改变了人物关系，也让主角重新认识自己真正想要的生活。结局回应开场的事件，并为后续留下新的可能。'};
 d={...generated,audience:settings.audience||generated.audience,genre:split(settings.genre,3).length?split(settings.genre,3):generated.genre,core:split(settings.core,3).length?split(settings.core,3):generated.core,style:split(settings.style,5).length?split(settings.style,5):generated.style};p.agent.demo=romance;p.original=text;p.sourceName=p.agent.entrySource||'用户故事想法';p.agent.planningOrigin='generated';p.agent.planningSeed=text;
 }else{p.agent.planningOrigin=prior?p.agent.planningOrigin:'manual';if(!p.original)p.original=text;}
 if(prior&&!manual)checkpoint(p);p.agent.planning=d;p.agent.phase='planning';p.agent.planningTab='overview';p.agent.planningUndo??=[];p.agent.planningRedo??=[];sync(p);return d;}
function checkpoint(p){p.agent.planningUndo??=[];p.agent.planningUndo.push(clone(p.agent.planning));p.agent.planningUndo=p.agent.planningUndo.slice(-30);p.agent.planningRedo=[];}
function set(p,key,value,record=true){if(!(key in labels))throw Error('Invalid story field');if(limits[key]){if(!Array.isArray(value))throw Error('Choose a tag');value=[...new Set(value.map(x=>x.trim()).filter(Boolean))];if(value.length>limits[key])throw Error('Select up to '+limits[key]+' tags for '+labels[key].toLowerCase()+'.');}if(JSON.stringify(p.agent.planning[key])===JSON.stringify(value))return;if(record)checkpoint(p);p.agent.planning[key]=value;sync(p);}
function travel(p,redo){const from=redo?'planningRedo':'planningUndo',to=redo?'planningUndo':'planningRedo';if(!p.agent[from]?.length)return;p.agent[to]??=[];p.agent[to].push(clone(p.agent.planning));p.agent.planning=p.agent[from].pop();sync(p);}
function missing(p){const d=p.agent.planning;return ['title','audience','genre','core','style','synopsis'].filter(k=>!d[k]?.length||typeof d[k]==='string'&&!d[k].trim());}
const api={enter,set,travel,sync,checkpoint,missing,limits,labels};if(typeof module!=='undefined')module.exports=api;else root.StoryPlanning=api;
})(globalThis);
